            firstSetReverted = true;
        } else {
            firstSetReverted = false;
        }

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool secondSetReverted;
        c.SetLogFile(secondLog); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondSetReverted = true;
