// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(address firstLog, address secondLog) internal {
        bool firstSetReverted;
        try c.SetLogFile(firstLog) {
            firstSetReverted = false;
        } catch {
            firstSetReverted = true;
        }
        try c.Initialized() {} catch { return; }
        bool secondSetReverted;
        try c.SetLogFile(secondLog) {
            secondSetReverted = false;
        } catch {
            secondSetReverted = true;
        }
        assertTrue(firstSetReverted == false && secondSetReverted == true);
    }

    function testFuzz_run(address firstLog, address secondLog) public {
        vm.assume(firstLog.code.length == 0 && uint160(firstLog) > 0xffff && firstLog != address(this) && firstLog != address(c) && firstLog != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && firstLog != 0x000000000000000000636F6e736F6c652e6c6f67 && firstLog != 0x4e59b44847b379578588920cA78FbF26c0B4956C && firstLog != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(secondLog.code.length == 0 && uint160(secondLog) > 0xffff && secondLog != address(this) && secondLog != address(c) && secondLog != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && secondLog != 0x000000000000000000636F6e736F6c652e6c6f67 && secondLog != 0x4e59b44847b379578588920cA78FbF26c0B4956C && secondLog != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(firstLog, secondLog);
    }

    receive() external payable {}
}
